import fs from 'node:fs';

const file = process.argv[2];
const lines = fs.readFileSync(file, 'utf8').split('\n').filter(Boolean);

let prevTs = null;
for (const line of lines) {
  let obj;
  try { obj = JSON.parse(line); } catch { continue; }
  const ts = obj.timestamp || obj.ts || (obj.message && obj.message.timestamp);
  let gap = '';
  if (ts && prevTs) {
    const d = (new Date(ts) - new Date(prevTs)) / 1000;
    if (d > 15) gap = `  [+${d.toFixed(0)}s]`;
  }
  if (ts) prevTs = ts;

  const type = obj.type || '?';
  let role = obj.message?.role || obj.role || '';
  let summary = '';

  const content = obj.message?.content || obj.content;
  if (typeof content === 'string') {
    summary = content.slice(0, 300).replace(/\n/g, ' ⏎ ');
  } else if (Array.isArray(content)) {
    const parts = [];
    for (const c of content) {
      if (c.type === 'text') parts.push('TEXT: ' + c.text.slice(0, 300).replace(/\n/g, ' ⏎ '));
      else if (c.type === 'tool_use') parts.push(`TOOL_USE(${c.name}): ` + JSON.stringify(c.input).slice(0, 250));
      else if (c.type === 'tool_result') {
        let rc = c.content;
        if (Array.isArray(rc)) rc = rc.map(x => x.text || '').join(' ');
        summary_result: {
          parts.push(`TOOL_RESULT${c.is_error ? '(ERROR)' : ''}: ` + String(rc).slice(0, 250).replace(/\n/g, ' ⏎ '));
        }
      }
    }
    summary = parts.join(' | ');
  }

  console.log(`${ts || '?'}${gap}  [${type}/${role}]  ${summary}`);
}

